RSpec.describe "forwarded Timekeeping setup helpers" do
  let(:arrange_company) { create(:company) }
  let(:arrange_actor) { create(:user, current_workspace_id: arrange_company.id) }
  let(:arrange_paul) do
    create(:user, first_name: "Paul", last_name: "Connors", email: "arrange-paul@example.com",
                  current_workspace_id: arrange_company.id)
  end
  let(:arrange_project) do
    create(:project, name: "Website", billable: true, client: create(:client, company: arrange_company, name: "Acme LLC"))
  end
  let(:arrange_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  # These examples pin the helpers without the live adapter, so they stay meaningful in a live regression run too.
  before { allow(TimekeepingRegressionAdapter).to receive(:current).and_return(nil) }

  # The copied setups every forwarded group used set the ownership singleton to owner
  # "timekeeping" at generation 2, gave the fake the same generation, registered the company,
  # the admin actor, paul and the project, and routed HTTP to the fake. The shared helper must
  # keep all of them, or forwarded imports in the migrated groups stop reaching the fake.
  # What a forwarded import then sends is checked by the importer and job specs, not here.
  it "arrange_forwarded_timekeeping hands ownership to the fake at generation 2 and routes Timekeeping HTTP to it" do
    stub_const("TimekeepingOwnerState::SELECTED", nil)
    %i[register_company register_user register_project].each do |method|
      allow(arrange_fake).to receive(method).and_call_original
    end
    allow(self).to receive(:route_timekeeping_to_fake).and_call_original

    arrange_forwarded_timekeeping(arrange_fake, company: arrange_company,
                                                users: { arrange_actor => "admin", arrange_paul => "employee" },
                                                project: arrange_project)

    ownership = TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID)
    expect(ownership).to have_attributes(owner: "timekeeping", generation: 2)
    expect(arrange_fake.generation).to eq(2)
    expect(arrange_fake).to have_received(:register_company)
      .once.with(id: arrange_company.id, edit_days: arrange_company.timesheet_edit_days)
    expect(arrange_fake).to have_received(:register_user).twice
    expect(arrange_fake).to have_received(:register_user).with(id: arrange_actor.id, company_id: arrange_company.id, role: "admin")
    expect(arrange_fake).to have_received(:register_user).with(id: arrange_paul.id, company_id: arrange_company.id, role: "employee")
    expect(arrange_fake).to have_received(:register_project).once.with(id: arrange_project.id, company_id: arrange_company.id)
    expect(self).to have_received(:route_timekeeping_to_fake).once.with(arrange_fake, base_url: FORWARDED_TIMEKEEPING_BASE_URL)
  end

  # Every copied setup this helper replaces set owner "timekeeping" with generation 2 on the ownership row
  # and on the fake, so a generation-bump example that starts from a leftover generation would not bump past it.
  it "resets ownership to timekeeping at generation 2 on both sides even when an earlier step left a later generation" do
    stub_const("TimekeepingOwnerState::SELECTED", nil)
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(owner: "monolith", generation: 7)
    arrange_fake.generation = 7
    allow(arrange_fake).to receive(:register_user).and_call_original

    arrange_forwarded_timekeeping(arrange_fake, company: arrange_company,
                                                users: { arrange_paul => "employee" },
                                                project: arrange_project)

    ownership = TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID)
    expect(ownership).to have_attributes(owner: "timekeeping", generation: 2)
    expect(arrange_fake.generation).to eq(2)
    # Only the users passed in are registered, so a spec whose actor has left the company can leave it out.
    expect(arrange_fake).to have_received(:register_user).once
    expect(arrange_fake).to have_received(:register_user).with(id: arrange_paul.id, company_id: arrange_company.id, role: "employee")
  end

  # "During a regression run, `arrange_forwarded_timekeeping` must follow the selected state and not flip the
  # row to Timekeeping at generation 2."
  it "arrange_forwarded_timekeeping with owner_state rollback leaves owner monolith, store prepared, generation 3" do
    arrange_forwarded_timekeeping(arrange_fake, company: arrange_company,
                                                users: { arrange_paul => "employee" },
                                                project: arrange_project,
                                                owner_state: "rollback")

    ownership = TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID)
    expect(ownership).to have_attributes(owner: "monolith", monolith_store: "prepared", generation: 3)
    expect(arrange_fake.generation).to eq(3)
  end

  it "arrange_forwarded_timekeeping with owner_state timekeeping leaves owner timekeeping, store legacy, generation 2" do
    arrange_forwarded_timekeeping(arrange_fake, company: arrange_company,
                                                users: { arrange_paul => "employee" },
                                                project: arrange_project,
                                                owner_state: "timekeeping")

    ownership = TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID)
    expect(ownership).to have_attributes(owner: "timekeeping", monolith_store: "legacy", generation: 2)
    expect(arrange_fake.generation).to eq(2)
  end

  # Real callers leave owner_state out, so a regression run reaches the selected state only through the default.
  it "arrange_forwarded_timekeeping without owner_state follows the selected rollback state" do
    stub_const("TimekeepingOwnerState::SELECTED", "rollback")

    arrange_forwarded_timekeeping(arrange_fake, company: arrange_company,
                                                users: { arrange_paul => "employee" },
                                                project: arrange_project)

    ownership = TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID)
    expect(ownership).to have_attributes(owner: "monolith", monolith_store: "prepared", generation: 3)
    expect(arrange_fake.generation).to eq(3)
  end

  # A helper that sets only owner and generation leaves monolith_store and the retired flag at the
  # leftover row's values, so the row starts different from the timekeeping state in every compared column.
  it "arrange_forwarded_timekeeping with no state selected leaves the whole ownership row equal to the timekeeping state" do
    stub_const("TimekeepingOwnerState::SELECTED", nil)
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID)
      .update_columns(owner: "monolith", monolith_store: "prepared", generation: 7, legacy_retired_at: nil)
    arrange_fake.generation = 7
    allow(arrange_fake).to receive(:register_user).and_call_original
    allow(arrange_fake).to receive(:register_project).and_call_original

    arrange_forwarded_timekeeping(arrange_fake, company: arrange_company,
                                                users: { arrange_paul => "employee" },
                                                project: arrange_project)

    expect_owner_state!("timekeeping")
    expect(TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID))
      .to have_attributes(owner: "timekeeping", monolith_store: "legacy", generation: 2,
                          legacy_retired_at: TimekeepingOwnerState::LEGACY_RETIRED_AT)
    expect(arrange_fake.generation).to eq(2)
    expect(arrange_fake).to have_received(:register_user)
      .once.with(id: arrange_paul.id, company_id: arrange_company.id, role: "employee")
    expect(arrange_fake).to have_received(:register_project)
      .once.with(id: arrange_project.id, company_id: arrange_company.id)
  end
end

RSpec.describe "forwarded Timekeeping environment helper" do
  # These examples pin the helper without the live adapter, so they stay meaningful in a live regression run too.
  before { allow(TimekeepingRegressionAdapter).to receive(:current).and_return(nil) }

  # Both variables must be set for a forwarded import: the base URL picks the service and the key
  # signs the user token. A helper that set only one, or leaked them past the block, would break
  # other examples that expect the legacy store.
  it "with_forwarded_timekeeping_env sets the base URL and signing key inside the block and restores both afterwards" do
    base_url_env = Timekeeping::EntryApiClient::BASE_URL_ENV
    key_env = Timekeeping::UserToken::PRIVATE_KEY_ENV
    previous = { base_url_env => ENV.fetch(base_url_env, nil), key_env => ENV.fetch(key_env, nil) }
    seen = nil

    with_forwarded_timekeeping_env do
      seen = { base_url_env => ENV.fetch(base_url_env, nil), key_env => ENV.fetch(key_env, nil) }
    end

    expect(FORWARDED_TIMEKEEPING_BASE_URL).to eq("http://timekeeping.test")
    expect(seen[base_url_env]).to eq("http://timekeeping.test")
    expect(seen[key_env]).to eq(timekeeping_key_pair.to_pem)
    expect(ENV.fetch(base_url_env, nil)).to eq(previous[base_url_env])
    expect(ENV.fetch(key_env, nil)).to eq(previous[key_env])

    with_forwarded_timekeeping_env("http://other-timekeeping.test") do
      expect(ENV.fetch(base_url_env, nil)).to eq("http://other-timekeeping.test")
    end
    expect(ENV.fetch(base_url_env, nil)).to eq(previous[base_url_env])
  end

  # An import that raises StaleGeneration or OwnershipMoving inside the block must not leave the
  # private key or base URL set for the next example, or later legacy examples would forward by accident.
  it "puts both Timekeeping environment variables back when the forwarded block raises" do
    with_timekeeping_env(
      Timekeeping::UserToken::PRIVATE_KEY_ENV => "outer-key",
      Timekeeping::EntryApiClient::BASE_URL_ENV => "http://outer.test"
    ) do
      seen = {}
      expect do
        with_forwarded_timekeeping_env do
          seen[:base_url] = ENV.fetch(Timekeeping::EntryApiClient::BASE_URL_ENV, nil)
          seen[:private_key] = ENV.fetch(Timekeeping::UserToken::PRIVATE_KEY_ENV, nil)
          raise Timekeeping::Gateway::StaleGeneration
        end
      end.to raise_error(Timekeeping::Gateway::StaleGeneration)

      expect(seen).to eq(base_url: "http://timekeeping.test", private_key: timekeeping_key_pair.to_pem)
      expect(ENV.fetch(Timekeeping::EntryApiClient::BASE_URL_ENV, nil)).to eq("http://outer.test")
      expect(ENV.fetch(Timekeeping::UserToken::PRIVATE_KEY_ENV, nil)).to eq("outer-key")
    end
  end
end

RSpec.describe "forwarded Timekeeping helpers with the live adapter running" do
  let(:adapter_company) { create(:company) }
  let(:adapter_user) { create(:user, current_workspace_id: adapter_company.id) }
  let(:adapter_project) { create(:project, client: create(:client, company: adapter_company)) }
  let(:adapter_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }
  let(:adapter_key) { OpenSSL::PKey::RSA.generate(2048) }
  let(:adapter_live) { double("live adapter instance", base_url: "http://127.0.0.1:4999", private_key: adapter_key) }

  before { allow(TimekeepingRegressionAdapter).to receive(:current).and_return(adapter_live) }

  # "With the adapter present, `arrange_forwarded_timekeeping` still applies its `owner_state:` but skips every
  # `fake.register_*` call and `route_timekeeping_to_fake`."
  it "arrange_forwarded_timekeeping applies the owner state but registers and routes nothing to the fake, even with an explicit base_url" do
    %i[register_company register_user register_project].each do |method|
      allow(adapter_fake).to receive(method).and_call_original
    end
    allow(self).to receive(:route_timekeeping_to_fake).and_call_original
    stubs_before = WebMock::StubRegistry.instance.request_stubs.size

    [{}, { base_url: "http://other-timekeeping.test" }].each do |base_url_option|
      arrange_forwarded_timekeeping(adapter_fake, company: adapter_company, users: { adapter_user => "admin" },
                                                  project: adapter_project, owner_state: "timekeeping", **base_url_option)

      expect(TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID))
        .to have_attributes(owner: "timekeeping", monolith_store: "legacy", generation: 2)
    end

    expect(self).not_to have_received(:route_timekeeping_to_fake)
    expect(WebMock::StubRegistry.instance.request_stubs.size).to eq(stubs_before)
    %i[register_company register_user register_project].each do |method|
      expect(adapter_fake).not_to have_received(method)
    end
    # "FakeTimekeeping records zero requests"
    expect(adapter_fake.requests).to be_empty
  end

  # "While the live adapter runs (`TimekeepingRegressionAdapter.current` non-nil), `with_forwarded_timekeeping_env`
  # uses the adapter's base URL and private key instead of `FORWARDED_TIMEKEEPING_BASE_URL` and the fake's key"
  it "with_forwarded_timekeeping_env yields the adapter URL and PEM, even for an explicit URL, and restores both keys, also when the block raises" do
    base_url_env = Timekeeping::EntryApiClient::BASE_URL_ENV
    key_env = Timekeeping::UserToken::PRIVATE_KEY_ENV
    adapter_values = { base_url: "http://127.0.0.1:4999", private_key: adapter_key.to_pem }

    with_timekeeping_env(base_url_env => "http://outer.test", key_env => "outer-key") do
      seen = nil
      with_forwarded_timekeeping_env do
        seen = { base_url: ENV.fetch(base_url_env, nil), private_key: ENV.fetch(key_env, nil) }
      end
      expect(seen).to eq(adapter_values)
      expect(seen[:private_key]).not_to eq(timekeeping_key_pair.to_pem)
      expect(ENV.fetch(base_url_env, nil)).to eq("http://outer.test")
      expect(ENV.fetch(key_env, nil)).to eq("outer-key")

      # An explicit URL does not take the connection away from the adapter.
      [[], ["http://other-timekeeping.test"]].each do |url_argument|
        seen_while_raising = nil
        expect do
          with_forwarded_timekeeping_env(*url_argument) do
            seen_while_raising = { base_url: ENV.fetch(base_url_env, nil), private_key: ENV.fetch(key_env, nil) }
            raise Timekeeping::Gateway::StaleGeneration
          end
        end.to raise_error(Timekeeping::Gateway::StaleGeneration)

        expect(seen_while_raising).to eq(adapter_values)
        expect(ENV.fetch(base_url_env, nil)).to eq("http://outer.test")
        expect(ENV.fetch(key_env, nil)).to eq("outer-key")
      end
    end
  end

  it "arrange_forwarded_timekeeping under the live adapter stores the timekeeping row and sends the fake no message at all" do
    # A double with no allowed messages fails the example on any call, a generation write included.
    untouchable_fake = double("FakeTimekeeping that must not be reached")

    arrange_forwarded_timekeeping(untouchable_fake, company: adapter_company, users: { adapter_user => "admin" },
                                                    project: adapter_project, owner_state: "timekeeping")

    expect_owner_state!("timekeeping")
  end
end

RSpec.describe "forwarded Timekeeping setup helpers in the legacy state" do
  let(:legacy_company) { create(:company) }
  let(:legacy_paul) { create(:user, current_workspace_id: legacy_company.id) }
  let(:legacy_project) { create(:project, client: create(:client, company: legacy_company)) }
  let(:legacy_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  # The helper leaves the fake untouched while the live adapter runs, so this pins the fake path without it.
  before { allow(TimekeepingRegressionAdapter).to receive(:current).and_return(nil) }

  it "arrange_forwarded_timekeeping with owner_state legacy leaves owner monolith, store legacy, generation 1 and fake generation 1" do
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(owner: "timekeeping", generation: 5)
    legacy_fake.generation = 5

    arrange_forwarded_timekeeping(legacy_fake, company: legacy_company,
                                               users: { legacy_paul => "employee" },
                                               project: legacy_project,
                                               owner_state: "legacy")

    # "`arrange_forwarded_timekeeping(owner_state: "legacy")` leaves owner monolith, store legacy, generation 1 and `fake.generation` 1"
    ownership = TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID)
    expect(ownership).to have_attributes(owner: "monolith", monolith_store: "legacy", generation: 1)
    expect(legacy_fake.generation).to eq(1)
  end
end

RSpec.describe "forwarded Timekeeping readers with the live adapter running" do
  let(:reader_live) { double("live adapter instance", base_url: "http://127.0.0.1:4999") }
  let(:reader_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }
  let(:reader_entries_url) { "http://127.0.0.1:4999/v1/companies/7/entries" }

  before do
    allow(TimekeepingRegressionAdapter).to receive(:current).and_return(reader_live)
    stub_request(:any, %r{\Ahttp://(127\.0\.0\.1:4999|127\.0\.0\.1:4998)/}).to_return(status: 200, body: "{}")
  end

  def send_reader_request(request_class, url, key: nil, body: nil)
    uri = URI(url)
    request = request_class.new(uri)
    request["Idempotency-Key"] = key if key
    request.body = JSON.generate(body) if body
    Net::HTTP.start(uri.host, uri.port) { |http| http.request(request) }
  end

  it "records every entry request sent to the live app, in order, and shows only the creates as creates" do
    send_reader_request(Net::HTTP::Post, reader_entries_url, key: "k1", body: { "note" => "a" })
    send_reader_request(Net::HTTP::Patch, "#{reader_entries_url}/12", key: "k2", body: { "note" => "b" })

    expect(forwarded_timekeeping_requests(reader_fake)).to eq(
      [
        { method: "POST", idempotency_key: "k1", body: { "note" => "a" } },
        { method: "PATCH", idempotency_key: "k2", body: { "note" => "b" } }
      ]
    )
    expect(forwarded_create_requests(reader_fake)).to eq([{ method: "POST", idempotency_key: "k1", body: { "note" => "a" } }])
    # The fake is not read while the live app owns the connection.
    expect(reader_fake.requests).to be_empty
  end

  # This example runs after the one above, which left two requests in the log.
  it "starts each example with an empty log, records identical creates twice and every path on the live app, and leaves out other addresses" do
    expect(forwarded_timekeeping_requests(reader_fake)).to eq([])

    2.times { send_reader_request(Net::HTTP::Post, reader_entries_url, key: "k1", body: { "note" => "a" }) }
    send_reader_request(Net::HTTP::Post, "http://127.0.0.1:4998/v1/companies/7/entries", key: "other-port")
    send_reader_request(Net::HTTP::Post, "http://127.0.0.1:4999/v1/companies/7/reservations", key: "other-path")

    expect(forwarded_timekeeping_requests(reader_fake).pluck(:idempotency_key)).to eq(%w[k1 k1 other-path])
  end

  it "admit_forwarded_generation with the live adapter running moves only the live admission row and sends the fake no message" do
    # A double with no allowed messages fails the example on any call, a generation write included.
    untouchable_fake = double("FakeTimekeeping that must not be reached")
    connection = double("live connection", close: nil)
    allow(connection).to receive(:exec_params).and_return(double("update result", cmd_tuples: 1))
    allow(PG).to receive(:connect).and_return(connection)

    admit_forwarded_generation(untouchable_fake, 3)

    expect(connection).to have_received(:exec_params)
      .with("UPDATE admission SET generation = $1 WHERE id = $2", [3, TimekeepingDatabaseReset::ADMISSION_ID]).once
  end
end

RSpec.describe "forwarded Timekeeping readers against the fake" do
  let(:reader_company) { create(:company) }
  let(:reader_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  before { allow(TimekeepingRegressionAdapter).to receive(:current).and_return(nil) }

  it "reads every request the fake received, on any path, with only the POST as a create" do
    entries_path = "/v1/companies/#{reader_company.id}/entries"
    reader_fake.call("POST", entries_path, headers: { "idempotency-key" => "k1" }, body: { "note" => "a" })
    reader_fake.call("PATCH", "#{entries_path}/12", headers: { "Idempotency-Key" => "k2" }, body: { "note" => "b" })
    reader_fake.call("GET", "/v1/companies/#{reader_company.id}/reservations")

    expect(forwarded_timekeeping_requests(reader_fake)).to eq(
      [
        { method: "POST", idempotency_key: "k1", body: { "note" => "a" } },
        { method: "PATCH", idempotency_key: "k2", body: { "note" => "b" } },
        { method: "GET", idempotency_key: nil, body: {} }
      ]
    )
    expect(forwarded_create_requests(reader_fake)).to eq([{ method: "POST", idempotency_key: "k1", body: { "note" => "a" } }])
  end

  it "counts each entry in the fake's outbox once, including an entry whose latest snapshot is discarded" do
    outbox = [
      { "entry" => { "id" => 1, "discarded_at" => nil } },
      { "entry" => { "id" => 1, "discarded_at" => nil } },
      { "entry" => { "id" => 2, "discarded_at" => nil } },
      { "entry" => { "id" => 3, "discarded_at" => nil } },
      { "entry" => { "id" => 3, "discarded_at" => "2026-01-07T00:00:00Z" } }
    ]
    allow(reader_fake).to receive(:outbox).and_return(outbox)

    expect(forwarded_stored_entry_count(reader_fake, company: reader_company)).to eq(3)
  end

  it "admit_forwarded_generation moves the fake's generation and opens no live database connection" do
    allow(PG).to receive(:connect)

    admit_forwarded_generation(reader_fake, 3)

    expect(reader_fake.generation).to eq(3)
    expect(PG).not_to have_received(:connect)
  end
end
